/* Global reset */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html, body {
  height: 100%;
  font-family: system-ui, sans-serif;
  background: var(--color-bg);
  color: var(--color-text);
  line-height: 1.5;
}

/* Layout */
.header {
  padding: 1rem;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  background: var(--color-primary);
  color: #fff;
}

.logo {
  height: 40px;
  width: auto;
}

.main {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 1rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

/* Status */
.status {
  font-weight: 600;
  text-align: center;
}

/* Video */
.videos {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  justify-content: center;
}

.videos video {
  width: 100%;
  max-width: 360px;
  border-radius: var(--radius);
  background: #000;
  object-fit: cover;
}

object-fit: cover;
}

/* Placeholder when no stream */
.placeholder::after {
  content: "No Stream";
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100%;
  color: var(--color-muted);
  font-size: 0.9rem;
  background: #222;
  border-radius: var(--radius);
}

/* Controls */
.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  justify-content: center;
}

.btn {
  padding: 0.5rem 1rem;
  border: none;
  border-radius: var(--btn-radius);
  background: var(--color-secondary);
  color: #fff;
  cursor: pointer;
  transition: var(--transition);
  font-size: 0.95rem;
}

.btn:focus-visible {
  outline: 3px solid var(--color-primary);
  outline-offset: 2px;
}

.btn:hover {
  background: #5a6268;
}

.btn.primary {
  background: var(--color-primary);
}

.btn.primary:hover {
  background: var(--color-primary-dark);
}

.btn.danger {
  background: var(--color-danger);
}

.btn.danger:hover {
  background: #c9302c;
}

.btn.secondary {
  background: var(--color-muted);
}

.btn.secondary:hover {
  background: #5a6268;
}

/* Regular (reg) button – used for refresh */
.btn.reg-btn {
  background: var(--color-primary);
}

.btn.reg-btn:hover {

}

.btn.reg-btn:hover {
  background: var(--color-primary-dark);
}

/* Chat */
.chat {
  border: 1px solid #ddd;
  border-radius: var(--radius);
  padding: 0.5rem;
}

.chat h2 {
  margin-bottom: 0.5rem;
  font-size: 1.2rem;
}

.chat-log {
  list-style: none;
  max-height: 150px;
  overflow-y: auto;
  margin-bottom: 0.5rem;
}

.chat-log li {
  margin-bottom: 0.3rem;
}

.chat-input {
  display: flex;
  gap: 0.5rem;
}

.chat-input input {
  flex: 1;
  padding: 0.5rem;
  border: 1px solid #ccc;
  border-radius: var(--radius);
}

.share {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
}

.share input {
  width: 100%;
  padding: 0.4rem;
  border: 1px solid #ccc;
  border-radius: var(--radius);
}

/* Footer */
.footer {
  text-align: center;
  font-size: 0.9rem;
  color: var(--color-muted);
  margin-top: 1rem;
}

/* Responsive */
@media (max-width: 480px) {
